/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AddTrustedMeasurementInput = {
  /** 64 hex characters, with or without a `sha256:` / `0x` prefix and in either case — it is normalised. */
  measurement: string;
  /** Why this cloud is trusted. Shown beside the entry. */
  note?: string | null | undefined;
};

export type AppendChatMessageInput = {
  content: string;
  error?: string | null | undefined;
  role: ChatRole;
  threadId: string | number;
  workspaceId: string | number;
};

export type AutoTopUpInput = {
  /** Micro-USD. Required when enabling. */
  amountMicros?: string | null | undefined;
  enabled: boolean;
  /** Micro-USD. Required when enabling. */
  thresholdMicros?: string | null | undefined;
};

/** Granularity of an activity series. Buckets start on UTC boundaries. */
export type Bucket =
  | 'DAY'
  | 'HOUR';

export type ChatCredentialInput = {
  workspaceId: string | number;
};

/** Where a console chat keeps its history. The console derives its own disclosure copy from this. */
export type ChatHistoryStorage =
  | 'ATTESTED_SERVER'
  | 'BROWSER_LOCAL';

/** Who said it. There is no system role. */
export type ChatRole =
  | 'ASSISTANT'
  | 'USER';

export type CreateApiKeyInput = {
  expiresAt?: string | null | undefined;
  /** Restrict the key to these model ids. Omit for all. */
  modelIds?: Array<string> | null | undefined;
  name: string;
  requestsPerMinute?: number | null | undefined;
  spendLimitMicros?: string | null | undefined;
  tokensPerMinute?: number | null | undefined;
  workspaceId: string | number;
};

export type CreateChatThreadInput = {
  modelId: string;
  workspaceId: string | number;
};

export type CreateCheckoutInput = {
  /** Micro-USD, a whole number of cents, at least `minTopUpMicros`. */
  amountMicros: string;
  workspaceId: string | number;
};

export type CreditTransactionKind =
  | 'ADJUSTMENT'
  | 'AUTO_TOPUP'
  | 'GRANT'
  | 'PURCHASE'
  | 'REFUND'
  | 'USAGE';

/** Whether the platform currently publishes a bundle for this endpoint, and whether it is inside the freshness window. A statement about publication only — the router never reports a verification verdict. */
export type EvidenceState =
  | 'NOT_PUBLISHED'
  | 'PUBLISHED'
  | 'STALE';

/** DIGEST_CHANGED and MEASUREMENT_CHANGED are reported on every change. Under two-factor trust a DIGEST_CHANGED is gating: the pinned digest no longer matches, so on an admitted endpoint it arrives with the DENIED_BY_THIS_ROUTER it caused. DIGEST_PINNED is an admin approving a deployment, and carries the digest. */
export type ExternalEndpointEventKind =
  | 'DENIED_BY_THIS_ROUTER'
  | 'DIGEST_CHANGED'
  | 'DIGEST_PINNED'
  | 'DISABLED'
  | 'KEY_ROTATED'
  | 'MEASUREMENT_CHANGED'
  | 'REGISTERED'
  | 'VERIFIED_BY_THIS_ROUTER';

/** What this router currently says about an upstream. Rendered as “verified by this router” / “denied by this router” — never a bare “verified”, which is reserved for nothing in this schema (ADR-002). PENDING is where every endpoint starts and restarts: no live verdict yet, so it serves nothing. */
export type ExternalEndpointStatus =
  | 'DENIED_BY_THIS_ROUTER'
  | 'DISABLED'
  | 'PENDING'
  | 'VERIFIED_BY_THIS_ROUTER';

/** A model on an external endpoint, and what this router charges for it. */
export type ExternalModelInput = {
  /** Defaults to CHAT — the one capability every OpenAI-compatible upstream serves. */
  capabilities?: Array<ModelCapability> | null | undefined;
  /** Micro-USD per 1M completion tokens. */
  completionPer1mMicros: string;
  contextLength: number;
  /** The public model id this router will publish, e.g. partner/llama-3.3-70b:tdx. A `String`, not an `ID`: it is a name the operator chooses here rather than a handle to something that already exists. */
  id: string;
  name: string;
  /** Micro-USD per 1M prompt tokens. */
  promptPer1mMicros: string;
  /** The name the upstream knows it by. */
  upstreamModel: string;
};

export type FeedbackIneligibleReason =
  | 'ALREADY_GRANTED'
  | 'BALANCE_HEALTHY'
  | 'DISABLED'
  | 'NO_FIRST_GRANT'
  | 'NO_USAGE';

export type GenerationFilter = {
  apiKeyIds?: Array<string | number> | null | undefined;
  from?: string | null | undefined;
  modelIds?: Array<string | number> | null | undefined;
  statuses?: Array<GenerationStatus> | null | undefined;
  to?: string | null | undefined;
};

export type GenerationSort = {
  direction?: SortDirection;
  field?: GenerationSortField;
};

export type GenerationSortField =
  | 'COST'
  | 'CREATED_AT'
  | 'LATENCY'
  | 'TOTAL_TOKENS';

export type GenerationStatus =
  | 'ABORTED'
  | 'ERROR'
  | 'OK';

/** Where an invitation code stands. A withdrawn code reads as withdrawn whatever else is true of it. */
export type InviteCodeStatus =
  | 'ACTIVE'
  | 'EXPIRED'
  | 'REDEEMED'
  | 'WITHDRAWN';

/** Why a presented invitation code did not credit this account. */
export type InviteRefusalReason =
  | 'ALREADY_REDEEMED'
  | 'DISABLED'
  | 'ERROR'
  | 'EXHAUSTED'
  | 'EXPIRED'
  | 'NOT_FOUND';

export type IssueInviteCodesInput = {
  /** Campaign tag: a lowercase slug, e.g. `launch-2026-10-devs`. */
  campaign: string;
  /** How many codes, 1–1000. */
  count: number;
  /** When the codes stop working. Null: never. */
  expiresAt?: string | null | undefined;
  /** Micro-USD each redemption grants, as an integer string. */
  grantMicros: string;
  /** Accounts that may redeem each code. */
  maxRedemptions?: number;
  note?: string | null | undefined;
};

/** Which anchor vouched for the measurement the verdict saw (SUP-139). */
export type MeasurementSource =
  | 'OPERATOR_PINNED'
  | 'REGISTRY';

export type ModelCapability =
  | 'CHAT'
  | 'COMPLETIONS'
  | 'EMBEDDINGS';

/** CONFIG is a model inside this deployment’s own cluster space, declared in the router config and therefore covered by the canonical snapshot a user pins. EXTERNAL is a model in another deployment, reached through this router’s attesting egress — the pin covers the verifier, not the upstream (ADR-008 §1). */
export type ModelOrigin =
  | 'CONFIG'
  | 'EXTERNAL';

export type PinExternalEndpointDigestInput = {
  /** The deployment to approve: sha256:<64 hex> (what the console shows) or sha256/<base64url>. Normalised. Replaces any earlier pin. */
  evidenceDigest: string;
};

export type RegisterExternalEndpointInput = {
  /** The upstream’s own LLM API key. Write-only: it is sealed before it reaches a column and no query returns it — only `apiKeyPrefix` comes back. */
  apiKey: string;
  /** https://host[:port]. Plain HTTP is refused — there is no channel to pin. */
  baseUrl: string;
  /** The models to publish, with this router’s prices. */
  models: Array<ExternalModelInput>;
  /** Lower-case letters, digits and hyphens; also the sidecar’s key. */
  name: string;
};

export type RotateExternalEndpointKeyInput = {
  /** The replacement upstream key. Rotation is a write; there is nothing to read. */
  apiKey: string;
};

export type SetAutoTopUpInput = {
  settings: AutoTopUpInput;
  workspaceId: string | number;
};

export type SetExternalEndpointEnabledInput = {
  /** Switching it back on returns it to PENDING: it re-attests from nothing. */
  enabled: boolean;
};

/** How an account came to exist. */
export type SignUpOrigin =
  | 'BOOTSTRAP'
  | 'INVITE'
  | 'OPEN';

export type SortDirection =
  | 'ASC'
  | 'DESC';

export type UpdateApiKeyInput = {
  expiresAt?: string | null | undefined;
  /** Replaces the scope. An empty list clears it. */
  modelIds?: Array<string> | null | undefined;
  name?: string | null | undefined;
  requestsPerMinute?: number | null | undefined;
  spendLimitMicros?: string | null | undefined;
  tokensPerMinute?: number | null | undefined;
};

export type UpdateExternalEndpointInput = {
  baseUrl?: string | null | undefined;
  /** Replaces the registered set. A model left out is retired, never deleted. */
  models?: Array<ExternalModelInput> | null | undefined;
};

export type UpdatePreferencesInput = {
  archiveEvidence?: boolean | null | undefined;
  desktopNotifications?: boolean | null | undefined;
  emailReceipts?: boolean | null | undefined;
  evidenceRetentionDays?: number | null | undefined;
  notifyOnMeasurementChange?: boolean | null | undefined;
};

export type UpdateProfileInput = {
  /** The display name shown in the console. Blank is not a name. */
  name: string;
};

/** An owner may spend the workspace’s credits; a member may only use them. */
export type WorkspaceRole =
  | 'MEMBER'
  | 'OWNER';

